static void smc_show(int n, int knob, pref_t r)
{
    (void)r;
    smc_ui_begin(n, knob);
}

static void smc_notice(int n)
{
    pref_t r = smc_target(n);
    uint8_t v = smc_scaled(r);
    uint8_t bit = (uint8_t)(1u << n);
    if (!smc_same(r, smc.target[n]) || v != smc.value[n]) {
        smc.target[n] = r;
        smc.value[n] = v;
        smc.picked &= (uint8_t)~bit;
        smc.pending |= bit;
    }
}

static void smc_fader(int n, uint8_t v)
{
    pref_t r;
    const x0x_param_t *d;
    uint8_t bit, old;
    int crossed, nv, moved;
    if (n < 0 || n >= 8)
        return;
    bit = (uint8_t)(1u << n);
    /* A repeated absolute sample is not a new gesture. Keep this history
     * separate from acceptance: target edits must retain crossing history. */
    moved = !(smc.input_seen & bit) || smc.last[n] != v;
    smc.input_seen |= bit;
    smc_notice(n);
    r = smc.target[n];
    d = pref_desc(r);
    if (!d || !d->max || r.kind == R_ACT || r.kind == R_HDR || r.kind == R_NONE) {
        smc.last[n] = v;
        smc.seen |= bit;
        return;
    }
    old = smc.value[n];
    crossed = smc_pickup_reached(smc.last[n], smc.seen & bit, old, v);
    smc.last[n] = v;
    smc.seen |= bit;
    if (!(smc.picked & bit)) {
        if (!moved || !crossed)
            goto show;
        smc.picked |= bit;
    } else crossed = 0;                /* acquisition must publish even an equal saved value */
    nv = (v * d->max + 63) / 127;
    if (crossed || nv != pref_get(r)) {
        pref_set(r, nv);
        motion_touch(r);
        smc.value[n] = smc_scaled(r);
        smc.pending |= bit;
    }
show:
    if (moved) {
        smc_show(n, 0, r);
        ui.act_t = plat_ms();
    }
}

static void smc_knob(int n, int delta)
{
    uint32_t saved_t;
    uint8_t saved_run;
    if (ui.overlay == O_ASK)
        return;
    if (!smc.locked && ui.overlay == O_NONE && smk_ck_smc_turn(n, delta))
        return;                          /* a SCALE / CHORD / ARP page owns its visible fields */
    pref_t r = smc_knob_target(n);
    if (r.kind == R_NONE || r.kind == R_HDR || r.kind == R_ACT) {
        if (r.kind == R_NONE && smc_fader_of(smc_page_target(n))) smc_show(n, 1, r);
        return;
    }
    /* Eight strips share one acceleration slot. Keep it off the panel encoders, and
     * start again when the finger moves to another strip. */
    saved_t = ui.enc_t[EN_K1];
    saved_run = ui.enc_run[EN_K1];
    if (smc.knob_i != (uint8_t)(n + 1)) {
        ui.enc_t[EN_K1] = 0;
        ui.enc_run[EN_K1] = 0;
        smc.knob_i = (uint8_t)(n + 1);
    } else {
        ui.enc_t[EN_K1] = smc.knob_t;
        ui.enc_run[EN_K1] = smc.knob_run;
    }
    /* The panel curve (up to x8, x16 on a wide range) is too far once the
     * relative byte has already counted the detents. A slow click stays one. */
    accel_smc = 1;
    turn_ref(r, delta, EN_K1);
    accel_smc = 0;
    smc.knob_t = ui.enc_t[EN_K1];
    smc.knob_run = ui.enc_run[EN_K1];
    ui.enc_t[EN_K1] = saved_t;
    ui.enc_run[EN_K1] = saved_run;
    ui.act_t = plat_ms();
    smc_show(n, 1, r);
}

static void smc_view(int v, int page)
{
    set_view(v);
    build_pages();
    if (page >= 0 && page < pg.n)
        *page_of(v) = (uint8_t)page;
}

static void smc_toggle_fx(int which)
{
    int param = which == 0 ? FX_RV_LEVEL : which == 1 ? FX_DL_LEVEL : FX_VOLUME;
    pref_t r = PR(R_ENG, T_FX, 0, param);
    int v = pref_get(r);
    if (v) {
        smc.fx_restore[which] = (uint8_t)v;
        pref_set(r, 0);
    } else
        pref_set(r, smc.fx_restore[which] ? smc.fx_restore[which] : 100);
}

static void smc_record_toggle(void)
{
    bass_step_cancel();                /* panel REC does this before key-up changes from step to note */
    ui.rec = !ui.rec;
    if (ui.rec && is_303())
        ui.wpos[bidx()] = 0;
    smc.rec_part = ui.part;
    say(ui.rec ? "RECORD ON" : "RECORD OFF", PART_N[ui.part]);
}

static void smc_select_part(int part)
{
    if (part != ui.part) {
        bass_step_cancel();             /* restore a held 303 step's sound before the page changes */
        drum_step_cancel();
    }
    ui.part = (uint8_t)part;
    ui.mixsel = (uint8_t)part;
    if (ui.view == V_GEN && !is_303())
        set_view(V_PART);
    ui.outline_ok = 0;
    build_pages();
}

static void smc_select_drum(int kit, int track)
{
    if (ui.sel[kit] != track) drum_step_cancel();
    ui.sel[kit] = (uint8_t)track;
    smc_select_part(kit);               /* the SMK pads and recording now share the visible drum's selection */
}

static int smc_bank(uint8_t note)
{
    if ((note == 0x2E || note == 0x2F) && ui.overlay == O_NONE &&
        !smk_clip_mode_on() && smc_drum_mix() >= 0) {
        int kit = smc_drum_mix();
        smc_select_drum(kit, note == 0x2E ? 0 : 8);
        return 1;
    }
    return 0;
}

static int smc_lock_blocks(uint8_t note)
{
    return smc.locked && (note < 8u || (note >= 24u && note < 32u) ||
        (note >= 0x2Eu && note <= 0x31u) || (note >= 0x60u && note <= 0x63u) ||
        (!smc.lock_kit && note >= 13u && note <= 15u));
}

static void smc_fx_publish(void)
{
    if (!smc.fx_ready) {
        int i;
        for (i = 0; i < SMCFX_N; i++)
            smc.fx_effect[i] = SMCFX_PAGE[0][i];
        smc.fx_page = 0;
        smc.fx_ready = 1;
    }
    /* The engine has one effect per bus. Peer zero wins a simultaneous
     * conflict; releasing it reveals peer one's still-held effect. */
    uint8_t down = 0, effects[SMCFX_N];
    for (int bus = 0; bus < SMCFX_N; bus++) {
        effects[bus] = SMCFX_PAGE[0][bus];
        for (unsigned peer = 0; peer < SMC_PEERS; peer++)
            if (smc_states[peer].fx_down & (1u << bus)) {
                down |= (uint8_t)(1u << bus);
                effects[bus] = smc_states[peer].fx_effect[bus];
                break;
            }
    }
    engine_smc_busfx(down, effects);
}

static void smc_fx_load_page(int page)
{
    int i, announce = smc.fx_ready;
    if (page < 0)
        page = SMCFX_NPAGE - 1;
    if (page >= SMCFX_NPAGE)
        page = 0;
    smc.fx_page = (uint8_t)page;
    for (i = 0; i < SMCFX_N; i++)
        smc.fx_effect[i] = SMCFX_PAGE[page][i];
    smc.fx_ready = 1;
    smc_fx_publish();
    if (announce)
        say(SMCFX_PAGE_NAME[page], "FX PAGE");
}

/* Translate physical strips only; effect IDs and held bus ownership stay stable. */
static int smc_fx_bus(uint8_t note)
{
    int bus = smcfx_bus(note);
    return bus >= 0 && bus < NPARTS ? part_at(bus) : bus;
}

static int smc_fx_bus_now(uint8_t note)
{
    if (ui.view != V_FX || ui.overlay != O_NONE || smk_clip_mode_on() || smc_drum_mix() >= 0)
        return -1;
    return smc_fx_bus(note);
}

static int smc_home_held(void)
{
    return smc.home_down || ((plat_buttons() >> B_HOME) & 1);
}

static void smc_fx_reset_cuts(void)
{
    int p;
    for (p = 0; p < NPARTS; p++) {
        uint8_t stored = proj.sound.v[T_MIX][NPARTS][p];
        pref_set(PR(R_ENG, T_MIX, p, MX_CUT), stored ? (int)stored - 1 : 127);
    }
    say("CUTOFF RESET", 0);
}

static void smc_fx_save_preset(void)
{
    int p;
    for (p = 0; p < NPARTS; p++)
        proj.sound.v[T_MIX][NPARTS][p] = (uint8_t)(pref_get(PR(R_ENG, T_MIX, p, MX_CUT)) + 1);
    mark_dirty();
    say("CUTOFF SAVED", 0);
}

static void smc_fx_show(uint8_t note)
{
    smc_ui.action = note;
    smc_ui_begin(note & 7, 3);
}

static void smc_fx_main_nav(int which)
{
    if (which < 0 || which > 2)
        return;
    smc_view(SMC_VIEW[3][which], SMC_PAGE[3][which]);
}

static void smc_fx_main_tick(void)
{
    int i;
    if (smc_fx_bus_now(24u) < 0) {
        smc_fx_clear();                 /* keyboard navigation cancels the original FX gesture */
        return;
    }
    for (i = 0; i < 3; i++) {
        uint8_t note = (uint8_t)(SMCFX_NOTE[SMCFX_RVB + i]);
        uint8_t sel = (uint8_t)(1u << (note - 24u));
        if (!(smc.fx_main_wait & (uint8_t)(1u << i)))
            continue;
        if (!(smc.select_down & sel)) {
            smc.fx_main_wait &= (uint8_t)~(1u << i);
            continue;
        }
        if ((uint32_t)(plat_ms() - smc.fx_main_t0[i]) >= SMC_FX_HOLD_MS)
            smc.fx_down |= (uint8_t)(1u << (SMCFX_RVB + i));
    }
    if (smc.fx_down)
        smc_fx_publish();
}

/* 1 = this note was an FX gesture (do not also run its old action). */
static int smc_fx_try(uint8_t note, int mmc)
{
    int bus;
    smc_fx_publish();
    if (smc_home_held() && ui.overlay == O_NONE && !smk_clip_mode_on() &&
        note >= 0x60 && note <= 0x63) {
        if (note >= 0x62)
            smc_fx_load_page((int)smc.fx_page + ((note & 1) ? 1 : -1));
        else if (note == 0x60)
            smc_fx_save_preset();
        else
            smc_fx_reset_cuts();
        return 1;
    }
    bus = smc_fx_bus_now(note);
    if (bus < 0)
        return 0;
    if (smc_home_held()) {
        smc.fx_effect[bus] = smcfx_cycle(bus, smc.fx_effect[bus]);
        smc_fx_publish();
        say(SMCFX_LONG[smc.fx_effect[bus]], SMCFX_BUS_NAME[bus]);
        smc_fx_show(note);
        return 1;                         /* assign only; the effect stays as it was */
    }
    if (!mmc) smc.fx_owned |= (uint8_t)(1u << bus);
    if (smcfx_is_main(bus)) {
        int which = bus - SMCFX_RVB;
        smc.fx_main_t0[which] = plat_ms();
        smc.fx_main_wait |= (uint8_t)(1u << which);
        return 1;                         /* tap navigates on release; hold arms momentary FX */
    }
    if (mmc)
        smc.fx_down ^= (uint8_t)(1u << bus);
    else
        smc.fx_down |= (uint8_t)(1u << bus);
    smc_fx_publish();
    say(SMCFX_LONG[smc.fx_effect[bus]], SMCFX_BUS_NAME[bus]);
    smc_fx_show(note);
    return 1;
}

static void smc_fx_release_note(uint8_t note)
{
    int bus = smc_fx_bus(note);
    if (bus < 0 || !(smc.fx_owned & (uint8_t)(1u << bus)))
        return;                         /* a non-FX press cannot acquire a release action later */
    smc.fx_owned &= (uint8_t)~(1u << bus);
    if (smcfx_is_main(bus)) {
        int which = bus - SMCFX_RVB;
        uint32_t dt = plat_ms() - smc.fx_main_t0[which];
        smc.fx_main_wait &= (uint8_t)~(1u << which);
        smc.fx_down &= (uint8_t)~(1u << bus);
        smc_fx_publish();
        if (smc_fx_bus_now(note) >= 0 && !smc_home_held() && dt < SMC_FX_HOLD_MS)
            smc_fx_main_nav(which);
        return;
    }
    smc.fx_down &= (uint8_t)~(1u << bus);
    smc_fx_publish();
}

static void smc_fx_clear(void)
{
    if (!smc.fx_down && !smc.fx_main_wait && !smc.fx_owned)
        return;
    smc.fx_owned = 0;
    smc.fx_down = 0;
    smc.fx_main_wait = 0;
    smc_fx_publish();
}

/* All four drum SEQ/MIX rows follow the visible fader/knob bank. Outside those
 * pages the strips retain their whole-part, FX and navigation functions. */
__attribute__((noinline))
static void smc_button_apply(uint8_t note, int mmc)
{
    int row, strip;
    if (ui.help && note == 6) {          /* R7 closes the card; every other control keeps working under it */
        ui.help = 0;
        return;
    }
    if (ui.overlay == O_ASK) {
        if (note == 5 || note == 6)
            button_tap(note == 5 ? B_SEL : B_HOME);
        return;
    }
    /* Lock freezes row identity as well as faders. SMC navigation and row REC
     * select a new context, so they wait for unlock. Global transport remains
     * live; recording/motion follow the current sequencer exactly as before. */
    if (smc_lock_blocks(note)) {
        ui_say("SMC TARGETS LOCKED", 0);
        return;
    }
    if (smc_fx_try(note, mmc))
        return;
    if (!smc.locked && ui.overlay == O_NONE && smk_ck_smc_nav(note))
        return;
    if (!mmc && note >= 8u && note < 16u && smc.solo_target[note - 8u])
        return;                        /* a held Solo's repeat cannot turn into a navigation shortcut */
    if (note < 32u) {
        int kit = smc_drum_mix();
        if (kit >= 0) {
            int track = smc_drum_track(kit, note & 7);
            if (track < 0) return;      /* bank 2's empty positions never become navigation shortcuts */
            switch (note >> 3) {
            case 0:
                smc_select_drum(kit, track);
                smc_record_toggle();
                break;
            case 1:
                smc_solo_press(note & 7, NPARTS + 1 + kit * NDRUM + track, mmc);
                say(smc.drum_solo[kit] & (1u << track) ? "SOLO" : "UNSOLO",
                    engine_voice_name(kit ? T_808 : T_909, track));
                break;
            case 2:
                mute_track(kit, track);
                break;
            default:
                /* A different sound still selects it. Press its SELECT again
                 * on a drum mixer to return to the main parts mixer. */
                if (ui.view == V_MIX && ui.part == kit && ui.sel[kit] == track)
                    smc_view(V_MIX, 0);
                else smc_select_drum(kit, track);
                break;
            }
            return;
        }
    }
    int nav_key = smc_nav_key(note);
    if (nav_key >= 0) {
        button_tap(nav_key);
        return;
    }
    if ((note == 0x30 || note == 0x31 ||
         ((note == 0x2E || note == 0x2F) && ui.view == V_PART && is_drum())) &&
        ui.overlay == O_NONE && !smk_clip_mode_on()) {
        int kit = smc_drum_mix();
        if (kit < 0 && ui.view == V_PART && is_drum()) kit = ui.part;
        if (kit >= 0) {
            int track = ui.sel[kit] + ((note & 1) ? 1 : -1);
            if (track >= 0 && track < NDRUM) smc_select_drum(kit, track);
            return;
        }
    }
    if (note < 32u) {
        row = note >> 3;
        strip = note & 7;
        if (strip < NPARTS) {
            int part = part_at(strip);
            if (row == 0) {             /* REC */
                smc_select_part(part);
                smc_record_toggle();
            } else if (row == 1) {      /* SOLO */
                smc_solo_press(strip, part + 1, mmc);
                say((smc.solo & (1u << part)) ? "SOLO" : "UNSOLO", PART_N[part]);
            } else if (row == 2)       /* MUTE */
                mute_part(part);
            else {                     /* SELECT */
                int repeat_drum = part < NKIT && ui.part == part && ui.overlay == O_NONE;
                smc_select_part(part);
                smc_view(repeat_drum ? V_MIX : V_PART, repeat_drum ? part + 1 : -1);
            }
        } else {
            int which = strip - NPARTS;
            if (row == 2)
                smc_toggle_fx(which);
            else
                smc_view(SMC_VIEW[row][which], SMC_PAGE[row][which]);
        }
        return;
    }
    if (smc_bank(note)) return;
    switch (note) {
    case 0x2E: case 0x30:             /* bank / channel left: part */
        if (part_position(ui.part) > 0) smc_select_part(part_neighbor(ui.part, -1));
        break;
    case 0x2F: case 0x31:
        if (part_position(ui.part) + 1 < NPARTS) smc_select_part(part_neighbor(ui.part, 1));
        break;
    case 0x5B: case 0x5C: {            /* rewind / forward: pattern */
        int part = smc.locked ? smc.lock_part : ui.part;
        int next = seq.ppat[part] + (note == 0x5B ? -1 : 1);
        if (next >= 0 && next < NPAT)
            seq_cue_part(&seq, part, next);
        break;
    }
    case 0x5D: seq_stop(&seq); break;
    case 0x5E:
        /* Match the keyboard's PLAY toggle, including a queued start before
         * the audio loop sees it. STOP retains its separate existing role. */
        if ((seq.playing || seq.req_start || seq.req_cont) && !seq.req_stop)
            seq_stop(&seq);
        else {
            seq.song_start = ui.song_sel < song()->len ? ui.song_sel : 0;
            seq_start(&seq);
        }
        break;
    case 0x5F:
        smc_record_toggle();
        break;
    case 0x60: case 0x61: case 0x62: case 0x63: {
        int d = (note & 1) ? 1 : -1;
        if (ui.overlay == O_LIST) {
            if (note < 0x62) list_move(d);
            else ui_menu_arrow(d);
        } else if (note < 0x62) {
            static const uint8_t views[] = {V_HOME, V_PART, V_SEQ, V_GEN, V_FX, V_MIX, V_SONG};
            int i = 0;
            while (i < 6 && views[i] != ui.view) i++;
            do { i = (i + d + 7) % 7; } while (views[i] == V_GEN && !is_303());
            smc_view(views[i], -1);
        } else {
            int p = cur_page() + d;
            if (p >= 0 && p < pg.n) *page_of(ui.view) = (uint8_t)p;
        }
        break;
    }
    default: break;
    }
}

static void smc_button(uint8_t note, int mmc)
{
    if (!mmc && note == 0x5Du) {
        smc_lock_button(1);
        return;                         /* no transport action card for target lock */
    }
    if (!mmc && note == 6)
        smc.home_down = 1;
    if (!mmc && note >= 24u && note < 32u) {
        uint8_t bit = (uint8_t)(1u << (note - 24u));
        if (smc.select_down & bit) return;
        smc.select_down |= bit;
    }
    if (!mmc && note == 0x5Eu) {
        if (smc.play_down) return;
        smc.play_down = 1;
    }
    char saved[sizeof ui.msg];
    uint32_t until = ui.msg_until;
    int kit = smc_drum_mix();
    int action = !smc_lock_blocks(note) && (note == 0x5Du || note == 0x5Eu || note == 0x5Fu ||
        (note < 24u && (kit >= 0 ? smc_drum_track(kit, note & 7u) >= 0 :
            (((note & 7u) < NPARTS && note != 14u) || note >= 16u))));
    memcpy(saved, ui.msg, sizeof saved);
    smc_ui_cancel();                     /* navigation owns its new screen immediately */
    smc_button_apply(note, mmc);
    if (smc_fx_bus_now(24u) < 0) smc_fx_clear(); /* queued SMC navigation also cancels holds */
    if (action) {
        memcpy(ui.msg, saved, sizeof saved);  /* Help keeps its card and the preexisting notice too. */
        ui.msg_until = until;
        smc_ui.action = note;
        smc_ui_begin(note < 32u ? note & 7u : 0, 3);
    }
}

static void smc_release(uint8_t note)
{
    if (note == 0x5Du) smc_lock_button(0);
    if (note == 6) smc.home_down = 0;
    if (note == 0x5Eu) smc.play_down = 0;
    smc_fx_release_note(note);
    if (smc_fx_bus_now(24u) < 0) smc_fx_clear(); /* a main tap may have navigated out of FX */
    if (note >= 24u && note < 32u)
        smc.select_down &= (uint8_t)~(1u << (note - 24u));
    if (note >= 8u && note < 16u && smc.solo_target[note - 8u]) {
        smc.solo_target[note - 8u] = 0; /* release the original target, even after navigation */
        smc_solo_publish();
    }
}

/* Stock User preset commands 1..32 run M/S/R/SELECT in strip order. */
static void smc_guarded_button(uint8_t note, int mmc, int allow)
{
    if (allow && !perf_testing())
        smc_button(note, mmc);
    else if (perf_testing() && (note == 6u || note == 0x5Du || note == 0x5Eu))
        button_tap(B_HOME);            /* STOP, PLAY and back use the panel abort/restore path */
}

static uint8_t smc_message(const uint8_t *m, uint8_t len, int allow)
{
    uint8_t type, ch, a, b, user = !!(proj.set.bt & PROJ_BT_SMC_USER);
    if (len == 6 && user && m[0] == 0xF0 && m[1] == 0x7F && m[2] == 0x7F &&
        m[3] == 0x06 && m[5] == 0xF7) {
        a = smc_mmc_note(m[4]);
        if (a == 0xFFu) return 4;
        smc_guarded_button(a, 1, allow);
        return !allow || perf_testing() ? 1 : 0;
    }
    if (len < 3)
        return 4;
    /* Never alias malformed BLE MIDI data bytes into SMC notes/CCs. */
    if ((m[1] | m[2]) & 0x80u)
        return 4;
    type = m[0] & 0xF0u;
    ch = m[0] & 0x0Fu;
    a = m[1] & 0x7Fu;
    b = m[2] & 0x7Fu;
    if (!allow || perf_testing()) {
        if (type == 0x90u && b && (!ch || user))
            smc_guarded_button(a, 0, 0);
        return 1;                     /* restoration still owns every other queued input */
    }
    if (type == 0xE0u && !user && ch < 8u)
        smc_fader(ch, (uint8_t)(((uint16_t)b << 7 | a) >> 7));
    else if (type == 0xB0u && a >= 16u && a < 24u && (user || ch == 0u)) {
        int delta = smc_relative(b);
        if (delta) smc_knob(a - 16u, delta);
    } else if (type == 0xB0u && user && a >= 40u && a < 48u)
        smc_fader(a - 40u, b);
    else if ((type == 0x90u || type == 0x80u) && (!ch || user)) {
        if (type == 0x90u && b) smc_button(a, 0);
        else smc_release(a);
    } else return 4; /* message is outside the selected preset's input format */
    return 0;
}

/* A full ring can refill while smc_poll drains it. Apply an overflowed STOP
 * at its original FIFO boundary, not merely at this poll's 16-item limit:
 * otherwise a preceding PLAY can execute on the next poll after STOP. */
static void smc_mmc_drain_stop(int src, int allow)
{
    uint32_t lost_stop = smc_mmc_stop_published[src];
    if (lost_stop != smc_mmc_stop_seen[src] &&
        smc_mmc_r[src] == smc_mmc_stop_boundary[src]) {
        smc_mmc_stop_seen[src] = lost_stop;
        if (proj.set.bt & PROJ_BT_SMC_USER)
            smc_guarded_button(0x5Du, 1, allow);
    }
}

static void smc_poll_peer(void)
{
    uint32_t link = smc_link_published;
    uint8_t r, count = 0;
    int allow = !perf_testing();
    smc_fx_main_tick();
    /* Snapshot producer generations before either input ring drains. An ISR
     * can enqueue a press then lose its release while another ring drains;
     * acknowledging that new loss in this poll would leave Solo latched. */
    uint32_t release_lost[4], release_seen[4];
    for (int i = 0; i < 4; i++) {
        release_lost[i] = smc_release_lost[i];
        release_seen[i] = smc_release_seen[i];
    }
    if (ui_project_busy()) {
        smc.lock_down

= smc.play_down = smc.select_down = smc.home_down = 0;
        smc_fx_clear();
        if (smc_project_active()) smc_solo_clear();
        smc_project_drop();
        return;
    }
    if (link != smc_link_seen) {
        /* Never clear the ISR's publication: it may already contain a newer
         * link edge than this snapshot. The next poll must still see it. */
        smc_link_seen = link;
        /* Skip pre-edge central packets without losing packets queued on the
         * newly connected link. Never rewind if another action already drained. */
        uint8_t cutoff = (uint8_t)(link >> 1);
        if ((uint8_t)(cutoff - smc_qr) <= (uint8_t)(smc_qw - smc_qr))
            smc_qr = cutoff;
        smc.up = (uint8_t)(link & 1u);
        smc.fresh = smc.up;
        smc.lock_down = smc.play_down = smc.select_down = smc.home_down = 0; /* reconnect clears physical press edges */
        smc_fx_clear();
        smc.picked = smc.seen = smc.input_seen = 0;
        smc.knob_i = 0;
        smc.pending = 0xFFu;
        for (int i = 0; i < 128; i++) smc.known[i] = 0;
        smc_solo_clear();              /* also covers a down/up pair coalesced before this poll */
        if (!smc.up) {
            ui_say("SMC LOST", 0);
        } else
            ui_say("SMC CONNECTED", 0);
    }
    /* Confirmation parks pickup and solos. Help does not. */
    if (!allow || ui.overlay == O_ASK) {
        smc.lock_down = smc.play_down = smc.select_down = smc.home_down = 0;
        smc_fx_clear();
        smc.picked = smc.seen = 0;
        smc.knob_i = 0;
        if (smc_project_active()) smc_solo_clear();
    }
    while (smc_qr != smc_qw && count++ < SMC_Q) {
        r = smc_qr;
        __asm__ volatile("" ::: "memory");
        smc_event_t msg = smc_q[r % SMC_Q];
        /* The ISR may reuse a full ring's slot as soon as the read index moves.
         * Keep a private event before releasing it. Release before dispatch so
         * a project action can still discard the remaining queued input. */
        __asm__ volatile("" ::: "memory");
        smc_qr = (uint8_t)(r + 1u);   /* an action can replace the project and discard the remaining queue */
        if (!smc.up) smc_reason = 2;
        else if (!(proj.set.bt & PROJ_BT_SMC_CENTRAL)) smc_reason = 3;
        else {
            if (allow && !perf_testing()) smc_dispatched++;
            smc_reason = smc_message(msg.b, msg.n, allow);
        }
    }
    if (smc_slot == 0) {
    count = 0;
    while (smc_host_r != smc_host_w && count++ < SMC_Q) {
        r = smc_host_r;
        uint8_t msg[3];
        __asm__ volatile("" ::: "memory");
        memcpy(msg, smc_host_q[r % SMC_Q], sizeof msg);
        __asm__ volatile("" ::: "memory");
        smc_host_r = (uint8_t)(r + 1u);
        if (proj.set.bt & PROJ_BT_SMC_USER)
            smc_message(msg, sizeof msg, allow);
    }
    for (int src = 0; src < 2; src++) {
        count = 0;
        while (smc_mmc_r[src] != smc_mmc_w[src] && count++ < 16u) {
            smc_mmc_drain_stop(src, allow);
            r = smc_mmc_r[src];
            __asm__ volatile("" ::: "memory");
            uint8_t cmd = smc_mmc_q[src][r % 16u];
            __asm__ volatile("" ::: "memory");
            smc_mmc_r[src] = (uint8_t)(r + 1u);
            if (proj.set.bt & PROJ_BT_SMC_USER)
                smc_guarded_button(smc_mmc_note(cmd), 1, allow);
        }
        /* The generation stays pending if an earlier queued command remains
         * beyond this poll's budget, preserving STOP-before-next-PLAY order. */
        smc_mmc_drain_stop(src, allow);
    }
    }
    /* A dropped Solo release is effective only after all presses queued
     * before the START-of-poll snapshot have been drained. Never consume a
     * newer ISR generation: its preceding press may still be queued. A
     * project drop may already have advanced a cursor; do not rewind it. */
    uint8_t missed_solo = 0;
    for (int i = 0; i < 4; i++)
        if (release_lost[i] != release_seen[i] && smc_release_seen[i] == release_seen[i]) {
            smc_release_seen[i] = release_lost[i];
            if (i < 2) missed_solo = 1;
            else smc.lock_down = 0;
        }
    if (missed_solo) {
        if (smc_project_active()) smc_solo_clear();
        /* The shared release-loss epoch also rearms edge-sensitive buttons.
         * Losing a key-up must never park PLAY, SELECT, or HOME until reconnect. */
        smc.play_down = smc.select_down = smc.home_down = 0;
        smc_fx_clear();
    }
    smc_lock_tick();
    if ((perf_testing() || ui.overlay == O_ASK) && smc_project_active())
        smc_solo_clear();              /* an earlier event in this batch may have transferred ownership */
}

void smc_poll(void)
{
    uint8_t saved = smc_slot;
    for (smc_slot = 0; smc_slot < SMC_PEERS; smc_slot++) smc_poll_peer();
    smc_slot = saved;
}

static int smc_led(int note)
{
    int strip = note & 7, row = note >> 3;
    if (smc_lock_blocks((uint8_t)note)) return 0;
    if (note < 32) {
        int kit = smc_drum_mix();
        if (kit >= 0) {
            int track = smc_drum_track(kit, strip);
            if (track < 0) return 0;
            if (row == 0) return ui.rec && ui.part == kit && ui.sel[kit] == track;
            if (row == 1) return !!(smc.drum_solo[kit] & (1u << track));
            if (row == 2) return track_muted(kit, track);
            return ui.sel[kit] == track;
        }
    }
    if (note == 5) return ui.overlay != O_NONE;
    if (note == 6) return 0;
    if (note == 7) return ui.view == V_HOME;
    if (note == 13) return ui.view == V_MIX;
    if (note == 14) return ui.view == V_GLO;
    if (note == 15) return ui.view == V_PART;
    if (note < 32) {
        if (strip < NPARTS) {
            int part = part_at(strip);
            /* Panel REC and part changes update ui.part / ui.rec without smc.rec_part. */
            if (row == 0) return ui.rec && ui.part == part;
            if (row == 1) return !!(smc.solo & (1u << part));
            if (row == 2) return part_muted(part);
            /* SELECT feedback follows the same mode as its press action. Source
             * bus identity follows the presentation mapping, not the strip index. */
            if (row == 3 && ui.view == V_FX && ui.overlay == O_NONE && !smk_clip_mode_on())
                return (smc.fx_down >> part) & 1;
            return ui.part == part;
        }
        /* Strips 6–8: M = mute/zero. R8/S6/S7/S8 are handled above; SELECT 6/7/8
         * open reverb, delay and master (drum SELECT was handled above). */
        if (row == 2) return pref_get(strip == 7 ? PR(R_ENG, T_FX, 0, FX_VOLUME) :
                                     smc_home_target(strip)) == 0;
        return (strip == 5 && ui.view == V_FX && cur_page() == 0) ||
               (strip == 6 && ui.view == V_FX && cur_page() == 1) ||
               (strip == 7 && ui.view == V_MIX && cur_page() == 3);
    }
    /* Existing Mackie NoteOn feedback route; physical LED identity still
     * needs native owner verification for the captured preset. */
    if (note == 0x5D) {
        int beat = smc_beat_lit(); /* keep phase current even while locked */
        return smc.locked || beat;
    }
    if (note == 0x5E) return seq.playing;
    if (note == 0x5F) return ui.rec;
    return 0;
}

static void smc_frame_peer(void)
{
    static const uint8_t global[11] = {0x2E, 0x2F, 0x5B, 0x5C, 0x5D, 0x5E, 0x5F, 0x60, 0x61, 0x62, 0x63};
    uint8_t msg[3];
    int i, n, want;
    if (ui_project_busy() || !smc.up || !(proj.set.bt & PROJ_BT_SMC_CENTRAL))
        return;
    for (i = 0; i < 8; i++) smc_notice(i);
    for (i = 0; i < 43; i++) {
        n = i < 32 ? i : global[i - 32];
        want = smc_led(n);
        if (smc.known[n] && smc.lit[n] == want) continue;
        msg[0] = 0x90;
        msg[1] = (uint8_t)n;
        msg[2] = (uint8_t)(want ? 127 : 0);
        if (!plat_ble_smc_send_slot(smc_slot, msg, 3)) return;
        smc.known[n] = 1;
        smc.lit[n] = (uint8_t)want;
    }
    for (i = 0; i < 8; i++)
        if (smc.pending & (1u << i)) {
            msg[0] = (uint8_t)(0xE0u + i);
            msg[1] = smc.value[i];
            msg[2] = smc.value[i];
            if (!plat_ble_smc_send_slot(smc_slot, msg, 3)) return;
            smc.pending &= (uint8_t)~(1u << i);
        }
}

void smc_frame(void)
{
    uint8_t saved = smc_slot;
    for (smc_slot = 0; smc_slot < SMC_PEERS; smc_slot++) smc_frame_peer();
    smc_slot = saved;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Sample-slot commands adapted from Felucca's editor.c, Copyright (C) 2026 Leo Kuroshita
 * (@kurogedelic), Hugelton Instruments. */
/* X0X's subset of Felucca's editor protocol (web/EDITOR_PROTOCOL.md):
 *   F0 7D 46 4C cmd args.. F7
 * INFO (1), PING (25) and the sample-slot commands SMP_BEGIN .. SMP_INFO (11..15), so
 * tools/fm1_sample_upload.py loads break loops into the user slots unchanged. The
 * parameter / preset / track commands are Felucca's instrument and are not answered. */
#define ED_HDR0 0x7D
#define ED_HDR1 0x46
#define ED_HDR2 0x4C
enum { ED_INFO = 1, ED_PROJECT = 9, ED_SMP_BEGIN = 11, ED_SMP_WRITE, ED_SMP_END, ED_SMP_ERASE, ED_SMP_INFO, ED_SMP_READ, ED_PING = 25,
       ED_DIAG = 33, ED_BT_TEST = 34, ED_CTL_READ = 37, ED_INLOG = 38, ED_BOOT_INFO = 39,
       ED_BOOT_BEGIN = 43, ED_BOOT_WRITE, ED_BOOT_READ, ED_BOOT_END, ED_BOOT_ABORT,
       ED_INSTALL = 48 };
#include "boot_screen.h"
#if BOARD_SMK37
/* ED_INLOG (SMK-37, read only, a76): the inbound recorder (app/smk_inlog.h). No arg or arg 0: the entry
 * count, fm1_ms now, then 2 words for each entry (the oldest first), each word 5 x 7 bits, low bits
 * first. Then the 40 stored clip velocities and the 40 stored clip channels (one byte each).
 * Arg 1: 1, padled_dirty, then 16 GRB words of padled_rgb (the colour to send) and 16 GRB words of the
 * last frame sent to the pads (padled_buf), each word 4 x 7 bits, low bits first.
 * Arg 6: versioned read-only pad sensor snapshot, or BUSY; see web/EDITOR_PROTOCOL.md. */
static void smk_inlog_reply(uint32_t arg);   /* main_fm1.c */
#endif
/* ED_CTL_READ (SMK-37 with Bluetooth, for tools/fm1_install.py; read only): the Bluetooth block
 * (x0x_ble_abi.h XB_FLASH_OFF, XB_FLASH_SIZE = fm1_flash_map.h FL_BLE_LO..FL_BLE_HI). Offset (3 x 7 bits,
 * from the block start), count (pairs, 7 bits) -> offset, the bytes packed 7 to 8 (as ED_SMP_READ).
 * An offset outside the block gets no reply; the count stops at the block end. 36 (ABI 3 CTL2_READ,
 * piece 2) is not used, so an ABI 3 tool gets no reply. */
/* ED_BT_TEST (SMK-37 with Bluetooth, for tools/ble_autotest.py): op 0 = query, 1 = clear the start
 * block (as BLUETOOTH OFF), 2 = restart the unit (a chip reset, as fm1_reboot; never the update
 * loader). Reply: op, BLUETOOTH setting, guard blocked, plat_ble_state(). */
static uint32_t ed_reboot_at;                /* fm1_ms + 1 when a restart was asked for (0: none) */
#define ED_READ_MAX 224u                     /* X0X: SMP_READ's bytes a frame (the break page draws the slots) */

static uint8_t ed_out[732];                  /* ED_INLOG with 64 entries: 732 B (tests/diag_size_test.py) */
static uint32_t ed_n;

static void ed_begin(uint32_t cmd)
{
    ed_out[0] = 0xF0;
    ed_out[1] = ED_HDR0;
    ed_out[2] = ED_HDR1;
    ed_out[3] = ED_HDR2;
    ed_out[4] = (uint8_t)cmd;
    ed_n = 5;
}
static void ed_b(uint32_t v)
{
    if (ed_n < sizeof ed_out - 1u)
        ed_out[ed_n++] = (uint8_t)(v & 0x7Fu);
}
static void ed_str(const char *s, uint32_t max)
{
    uint32_t i;
    for (i = 0; s && s[i] && i < max; i++)
        ed_b((uint8_t)s[i] & 0x7Fu);
    ed_b(0);
}
static int ed_send(void)
{
    ed_out[ed_n++] = 0xF7;
    return ota_wire_send(ed_out, ed_n);
}

/* EC-026: a volatile mutation watch, not a lock or authentication mechanism.
 * No project/OTA scratch is retained. A START retry cannot clear dirty state.
 * The per-boot ticket defeats A -> B -> delayed A / old COMMIT interleaving.
 * Full hostile START+COMMIT replay across reboot is not authenticated here. */
#define ED_INSTALL_TOKEN 16u
#define ED_INSTALL_TICKET_MAX 0x0FFFFFFFu
static struct {
    uint32_t serial, ticket;
    uint8_t token[ED_INSTALL_TOKEN], state; /* 0 none, 1 watching, 2 dirty, 3 consumed */
} ed_install;
static uint8_t ed_install_pending; /* 1 authorize, 2 discard legacy requests after failed COMMIT */
static void ed_install_dirty(void)
{
    if (ed_install.state == 1u)
        ed_install.state = 2u;
}
static void ed_install_forget(void)
{
    if (ed_install.state)
        ed_install.state = 3u;
    ed_install_pending = 0;
}

static uint32_t ed_unpack7(const uint8_t *a, uint32_t na, uint8_t *out, uint32_t max)
{
    uint32_t n = 0;
    while (na && n < max) {
        uint32_t m = *a++, j;
        na--;
        for (j = 0; j < 7u && na && n < max; j++, na--)
            out[n++] = (uint8_t)(*a++ | ((m >> j) & 1u) << 7);
    }
    return n;
}
/* n bytes packed 7 to 8: a byte of high bits, then up to 7 low 7-bit bytes (ED_SMP_READ, ED_CTL_READ) */
static void ed_put7(const uint8_t *src, uint32_t n)
{
    uint32_t k, j;
    for (k = 0; k < n; k += 7) {
        uint32_t m = 0;
        for (j = 0; j < 7u && k + j < n; j++)
            m |= (uint32_t)(src[k + j] >> 7) << j;
        ed_b(m);
        for (j = 0; j < 7u && k + j < n; j++)
            ed_b(src[k + j]);
    }
}
/* Sample/project chunk staging: 512 B, live only for the duration of one ed_handle
 * (fill then consume; no cross-message retention). On the device this aliases the
 * main-loop scratch at OTA_DEC_OFF (x0x.c ED_SMP_SCRATCH), the same call-scoped
 * ownership class as ota_dec / PROJECT_IO_BUFFER. Host builds keep a private buffer. */
#define ED_SMP_BUF_SIZE 512u
#ifdef ED_SMP_SCRATCH
_Static_assert(ED_SMP_BUF_SIZE <= 640u, "ed_smp_buf fits the ota_dec region");
#define ed_smp_buf ED_SMP_SCRATCH
#else
static uint8_t ed_smp_buf[ED_SMP_BUF_SIZE] __attribute__((aligned(4)));
#endif

/* Unlike the legacy decoder, reject truncated groups, excess bytes and noncanonical
 * high-bit masks. A malformed frame must never be accepted as a shorter write. */
static uint32_t ed_unpack_exact(const uint8_t *a, uint32_t na, uint8_t *out, uint32_t max)
{
    uint32_t n = na - (na + 7u) / 8u, i, pos = 0;
    if (!n || n > max || na % 8u == 1u)
        return 0;
    while (na) {
        uint32_t mask = *a++, take = --na > 7u ? 7u : na;
        if (mask >> take)
            return 0;
        for (i = 0; i < take; i++, na--) {
            if (*a & 0x80u)
                return 0;
            out[pos++] = (uint8_t)(*a++ | ((mask >> i) & 1u) << 7);
        }
    }
    return n;
}

/* PROJECT version 1. The project-stage allocation doubles as UI undo storage;
 * ui_project_begin freezes input/audio, and end restores that storage on every exit.
 * A browser restores sample slots only while mode 2 holds this lock, after VALIDATE. */
static struct {
    uint32_t at, next;
#if X0X_BASS_TAGGED_SOUND
    uint32_t size;
    uint8_t legacy_prepared;
#endif
    uint32_t sample_len[SMP_USER_SLOTS], sample_crc[SMP_USER_SLOTS];
    uint8_t mode, valid, changed, recovery, header[PROJECT_FILE_HDR];
} ed_project;
#if X0X_BASS_TAGGED_SOUND
#define ED_PROJECT_SIZE ed_project.size
#else
#define ED_PROJECT_SIZE PROJECT_FILE_SIZE
#endif

static uint32_t ed_project_sample_len(uint32_t k)
{
    const smp_user_hdr_t *h = (const smp_user_hdr_t *)smp_user_xip(k);
    return usr_nz[k] ? SMP_USER_DATA + h->data_len : 0;
}
static void ed_project_sample_snapshot(void)
{
    uint32_t k;
    for (k = 0; k < SMP_USER_SLOTS; k++) {
        uint32_t n = ed_project_sample_len(k);
        ed_project.sample_len[k] = n;
        ed_project.sample_crc[k] = n ? st_crc32(smp_user_xip(k), n) : 0;
    }
}
static int ed_project_samples_restored(void)
{
    uint32_t k;
    if (!ed_project.changed)
        return 1;
    for (k = 0; k < SMP_USER_SLOTS; k++) {
        uint32_t n = ed_project_sample_len(k);
        if (n != ed_project.sample_len[k] || (n && st_crc32(smp_user_xip(k), n) != ed_project.sample_crc[k]))
            return 0;
    }
    return 1;
}

static uint32_t ed_u21(const uint8_t *a)
{
    return (uint32_t)a[0] | (uint32_t)a[1] << 7 | (uint32_t)a[2] << 14;
}
static void ed_w21(uint32_t v) { ed_b(v); ed_b(v >> 7); ed_b(v >> 14); }
static uint8_t *ed_project_byte(uint32_t off)
{
    return off < PROJECT_FILE_HDR ? &ed_project.header[off] : (uint8_t *)&project_stage + off - PROJECT_FILE_HDR;
}
static int ed_project_samples_locked(void)
{
    return ed_project.mode == 1 || (ed_project.mode == 2 && !ed_project.valid);
}
static int ed_project_end(int apply)
{
    if (ed_project.mode) {
        if (!apply && !ed_project_samples_restored()) {
            ed_project.recovery = 1;
            ui_say("SAMPLE RECOVERY NEEDED", "");
            return 2;                               /* never resume old music against partial samples */
        }
        ed_project.mode = 0;
        ed_project.recovery = 0;
        ui_project_end(apply);
    }
    return 0;
}
static uint32_t ed_project_rc(int rc)
{
    return rc == 0 ? 0u : rc == UI_PROJECT_BUSY ? 2u : rc == -4 ? 4u : rc == -7 ? 6u : rc == -10 ? 9u : 5u;
}
static void ed_project_handle(const uint8_t *a, uint32_t na)
{
    uint32_t op, rc = 0, off = 0, n = 0, i;
    if (!na)
        return;
    op = *a++; na--;
    ed_b(op);
    if (ed_project.mode)
        ed_project.at = fm1_ms;
    switch (op) {
    case 64:                                        /* QUERY / keepalive */
        if (na) { rc = 1; break; }
        ed_b(0); ed_b(X0X_BASS_TAGGED_SOUND?2:1); ed_w21(PROJECT_FILE_SIZE); ed_b(ed_project.recovery ? 3 : ed_project.mode);
        return;
    case 65:                                        /* EXPORT BEGIN */
    case 67:                                        /* IMPORT BEGIN */
#if X0X_BASS_TAGGED_SOUND
        if(op==65 && (project_storage_unsupported() || engine_bass_sound_validate(&proj.sound) ||
           engine_bass_preset_pending(0) || engine_bass_preset_pending(1))) {rc=2;break;}
#elif X0X_BASS_PRESET_PREVIEW
        if(op==65 && engine_bass_preview_changed()) { rc=2; break; }
#endif
        if ((op == 65 && na) || (op == 67 && (na != 3 || (ed_u21(a) != PROJECT_FILE_SIZE
#if X0X_BASS_TAGGED_SOUND
            && ed_u21(a)!=PROJECT_LEGACY_FILE_SIZE
#endif
            )))) {
            rc = 1; break;
        }
        if (op == 67 && ed_project.recovery) {
            ed_project.recovery = 0;                 /* recover under the existing audio/input hold */
        } else {
            if (ed_project.mode || ui_project_begin()) { rc = 2; break; }
            ed_project.changed = 0;
            if (op == 67)
                ed_project_sample_snapshot();
        }
#if X0X_BASS_TAGGED_SOUND
        ed_project.size=op==65?PROJECT_FILE_SIZE:ed_u21(a);
        ed_project.legacy_prepared=0;
#endif
        ed_project.mode = (uint8_t)(op == 65 ? 1 : 2);
        ed_project.at = fm1_ms;
        ed_project.next = 0;
        ed_project.valid = 0;
        if (op == 65) {
            project_capture_stage();
            project_file_header(ed_project.header);
            ed_b(0); ed_w21(PROJECT_FILE_SIZE);
            return;
        }
        break;
    case 66:                                        /* READ */
        if (ed_project.mode != 1) { rc = 2; break; }
        if (na != 5) { rc = 1; break; }
        off = ed_u21(a); n = (uint32_t)a[3] | (uint32_t)a[4] << 7;
        if (!n || n > ED_READ_MAX || off > ED_PROJECT_SIZE || n > ED_PROJECT_SIZE - off) {
            rc = 1; break;
        }
        for (i = 0; i < n; i++)
            ed_smp_buf[i] = *ed_project_byte(off + i);
        ed_b(0); ed_w21(off); ed_put7(ed_smp_buf, n);
        return;
    case 68:                                        /* sequential WRITE, exact retries are idempotent */
        if (ed_project.mode != 2) { rc = 2; break; }
#if X0X_BASS_TAGGED_SOUND
        if(ed_project.legacy_prepared) {rc=2;break;} /* representation is now staged/quarantined */
#endif
        if (na < 5) { rc = 1; break; }
        off = ed_u21(a);
        n = ed_unpack_exact(a + 3, na - 3, ed_smp_buf, ED_READ_MAX);
        if (!n || off > ED_PROJECT_SIZE || n > ED_PROJECT_SIZE - off) { rc = 1; break; }
        if (off > ed_project.next || (off < ed_project.next && n > ed_project.next - off)) {
            rc = 3; break;
        }
        if (off < ed_project.next) {
            for (i = 0; i < n; i++)
                if (*ed_project_byte(off + i) != ed_smp_buf[i]) { rc = 3; break; }
            if (rc) break;
        } else {
            ed_project.valid = 0;
            for (i = 0; i < n; i++)
                *ed_project_byte(off + i) = ed_smp_buf[i];
            ed_project.next += n;
        }
        ed_b(0); ed_w21(ed_project.next);
        return;
    case 69:                                        /* COMMIT, deliberately never saved implicitly */
    case 74:                                        /* VALIDATE before any sample write */
        if (ed_project.mode != 2) { rc = 2; break; }
        if (op == 69 && (na != 2 || a[0] != 0x58 || a[1] != 0x30)) { rc = 8; break; }
        if (op == 74 && na) { rc = 1; break; }
        if (ed_project.next != ED_PROJECT_SIZE) { rc = 3; break; }
#if X0X_BASS_TAGGED_SOUND
        if(ed_project.legacy_prepared) {rc=9;break;}
        if(ED_PROJECT_SIZE!=PROJECT_FILE_SIZE) {
            int result=project_prepare_legacy_file(ed_project.header);
            if(result==-10)ed_project.legacy_prepared=1;
            rc=ed_project_rc(result);break;
        }
#endif
        rc = ed_project_rc(project_file_validate(ed_project.header));
        ed_project.valid = rc == 0;
        /* Validation may migrate a legacy BREAK mode byte. Canonicalize the
         * header so a later VALIDATE/COMMIT checks the migrated bytes' CRC. */
        if (!rc) project_file_header(ed_project.header);
        if (!rc && op == 69)
            ed_project_end(1);
        break;
#if X0X_BASS_TAGGED_SOUND
    case 75: /* Explicit legacy identity adoption: bankA,bankB,0x58,0x30; COMMIT remains separate. */
        if(ed_project.mode!=2 || !ed_project.legacy_prepared) {rc=2;break;}
        if(na!=4 || a[2]!=0x58 || a[3]!=0x30) {rc=8;break;}
        rc=ed_project_rc(project_adopt_legacy_stage(a[0],a[1]));
        if(!rc) {
            ed_project.legacy_prepared=0;ed_project.size=PROJECT_FILE_SIZE;
            ed_project.next=PROJECT_FILE_SIZE;ed_project.valid=1;
            project_file_header(ed_project.header);
        }
        break;
#endif
    case 70:                                        /* ABORT, including an already expired session */
        if (na) { rc = 1; break; }
        rc = (uint32_t)ed_project_end(0);
        break;
    case 71:                                        /* SAVE */
    case 72:                                        /* LOAD SAVED */
    case 73: {                                      /* RESET */
        int result;
        if (ed_project.mode) { rc = 2; break; }
        if (op == 71 ? na != 0 : na != 2 || a[0] != 0x58 || a[1] != 0x30) {
            rc = op == 71 ? 1 : 8; break;
        }
        result = op == 71 ? ui_project_save() : op == 72 ? ui_project_load() : ui_project_reset();
        rc = result == UI_PROJECT_BUSY ? 2u : result == -7 ? 6u : result ? 7u : 0u;
        break;
    }
    default: rc = 1; break;
    }
    ed_b(rc);
}

static uint32_t ed_smp_slot(uint32_t k) { return SMP_USER_OFF(k); }
/* Armed for rewrite: WRITE may touch the slot. Flash stays intact until the first
 * sector erase, so cancel after BEGIN alone keeps the last good sample. */
static uint8_t smp_importing[SMP_USER_SLOTS];
static uint8_t smp_sec0_erased[SMP_USER_SLOTS];
static void ed_smp_inval(uint32_t k)
{
    fm1_irq_off();
    fl_inval(ed_smp_slot(k), SMP_USER_SIZE(k));
    fm1_irq_on();
}
/* Drop live use of slot k before flash rewrite. Does not erase. */
static void ed_smp_retire(uint32_t k)
{
    if (!usr_nz[k])
        return;
    usr_nz[k] = 0;
    engine_brk_loops();                               /* the next trigger reads the replacement, not this slot */
    engine_brk_drop_range(smp_user_xip(k), SMP_USER_SIZE(k));
}
/* Silence audio then erase one 4 KiB sector (import / boot flash paths). */
static int ed_silence_erase4k(uint32_t off, uint32_t *took)
{
    uint32_t local;
    if (!took)
        took = &local;
    audio_silence();
    return fl_erase4k(off, took);
}
#if SMP_SEC0_BACKUP
/* Erase 4 KiB at dst and program from src through ed_smp_buf (backup and restore). */
static int ed_smp_copy_4k(uint32_t dst, const uint8_t *src)
{
    uint32_t i;
    if (ed_silence_erase4k(dst, 0))
        return 1;
    for (i = 0; i < 0x1000u; i += 256u) {
        uint32_t n = 0x1000u - i;
        if (n > 256u)
            n = 256u;
        memcpy(ed_smp_buf, src + i, n);
        if (fl_write(dst + i, ed_smp_buf, n))
            return 1;
        fm1_wdt_feed();
    }
    return 0;
}
/* Copy live sector 0 into FL_SMPV before the first destructive erase. */
static int ed_smp_backup_sec0(uint32_t k)
{
    return ed_smp_copy_4k(SMP_SEC0_BACKUP_OFF(k), smp_user_xip(k));
}
static int ed_smp_backup_present(uint32_t k)
{
    const smp_user_hdr_t *h = (const smp_user_hdr_t *)fm1_xip_ptr(SMP_SEC0_BACKUP_OFF(k));
    return h->magic == SMP_USER_MAGIC && h->version == 1 && h->nz && h->nz <= 16u;
}
static void ed_smp_clear_backup(uint32_t k)
{
    if (!ed_smp_backup_present(k))
        return;
    (void)ed_silence_erase4k(SMP_SEC0_BACKUP_OFF(k), 0);
}
/* Put sector 0 back from FL_SMPV when an import aborted after erasing it. */
static int ed_smp_restore_sec0(uint32_t k)
{
    uint32_t dst = ed_smp_slot(k);
    const uint8_t *src;
    if (!ed_smp_backup_present(k))
        return 1;
    src = fm1_xip_ptr(SMP_SEC0_BACKUP_OFF(k));
    if (ed_smp_copy_4k(dst, src))
        return 1;
    ed_smp_inval(k);
    smp_user_scan(k);
    smp_sec0_erased[k] = 0;
    smp_importing[k] = 0;
    ed_smp_clear_backup(k);
    engine_brk_loops();
    return usr_nz[k] ? 0 : 1;
}
/* Recover last-good after a failed END, a new BEGIN, or boot (power loss). */
static void ed_smp_try_restore(uint32_t k)
{
    if (usr_nz[k]) {
        ed_smp_clear_backup(k);
        return;
    }
    if (ed_smp_backup_present(k))
        (void)ed_smp_restore_sec0(k);
}
void ed_smp_recover(void)
{
    uint32_t k;
    for (k = 0; k < SMP_USER_SLOTS; k++)
        ed_smp_try_restore(k);
}
#else
static int ed_smp_backup_sec0(uint32_t k) { (void)k; return 0; }
static void ed_smp_clear_backup(uint32_t k) { (void)k; }
static void ed_smp_try_restore(uint32_t k) { (void)k; }
void ed_smp_recover(void) {}
#endif
static int ed_smp_begin(uint32_t k)
{
    ed_smp_try_restore(k);                            /* prior abandon / power-loss mid-WRITE */
    if (ed_project.mode == 2)
        ed_project.changed = 1;
    smp_importing[k] = 1;
    smp_sec0_erased[k] = 0;
    return 0;
}
static int ed_smp_erase(uint32_t k, uint32_t all)
{
    uint32_t i;
    int rc = 0;
    if (ed_project.mode == 2)
        ed_project.changed = 1;
    ed_smp_retire(k);
    smp_importing[k] = 0;
    smp_sec0_erased[k] = 0;
    ed_smp_clear_backup(k);
    for (i = 0; i < (all ? SMP_USER_SIZE(k) / 0x1000u : 1u) && !rc; i++) {
        rc = ed_silence_erase4k(ed_smp_slot(k) + i * 0x1000u, 0);
        fm1_wdt_feed();
    }
    ed_smp_inval(k);
    return rc;
}
/* Erase the 4 KiB sector that holds off. Sector 0 is deferred until the first
 * WRITE into it (BEGIN no longer wipes the header). Before that erase, shadow
 * sector 0 into FL_SMPV so cancel / failed END can restore last-good.
 * Higher sectors: FL_SMPV only holds sector 0, so wiping past 0x1000 already
 * destroys unrecoverable last-good. Clear any sec0 shadow (do not restore a
 * header over wiped data) and, if sector 0 is still live, erase it too so a
 * valid header cannot outlive its higher-sector payload. */
static int ed_smp_erase_for_write(uint32_t k, uint32_t off, uint32_t *took)
{
    if (off < 0x1000u) {
        if (smp_sec0_erased[k])
            return 0;
        if (usr_nz[k] && ed_smp_backup_sec0(k))
            return 1;                                 /* refuse wipe if shadow cannot be stored */
        ed_smp_retire(k);
        if (ed_silence_erase4k(ed_smp_slot(k), took))
            return 1;
        smp_sec0_erased[k] = 1;
        ed_smp_inval(k);
        return 0;
    }
    if (off & 0xFFFu)
        return 0;
    if (!smp_sec0_erased[k]) {
        /* First destructive touch is past sector 0: last-good cannot be kept. */
        ed_smp_retire(k);
        if (ed_silence_erase4k(ed_smp_slot(k), took))
            return 1;
        smp_sec0_erased[k] = 1;
        ed_smp_inval(k);
    } else {
        ed_smp_retire(k);
    }
    if (ed_silence_erase4k(ed_smp_slot(k) + off, took))
        return 1;
    ed_smp_clear_backup(k);                           /* sec0-only shadow would lie after this */
    return 0;
}
static int ed_smp_end(uint32_t k, const uint8_t *a, uint32_t na)
{
    const smp_user_hdr_t *h = (const smp_user_hdr_t *)ed_smp_buf;
    uint32_t n = ed_unpack_exact(a, na, ed_smp_buf, ED_SMP_BUF_SIZE);
    if (n != sizeof(smp_user_hdr_t) && n != SMP_USER_DATA) {
        ed_smp_try_restore(k);
        return 1;
    }
    if (h->magic != SMP_USER_MAGIC || h->version != 1 || !h->nz || h->nz > 16u ||
        h->data_len > SMP_USER_SIZE(k) - SMP_USER_DATA) {
        ed_smp_try_restore(k);
        return 2;
    }
    /* NOR can only clear bits. Programming a new header onto a live sector 0
     * AND-corrupts the previous one (BEGIN no longer erases). Require a WRITE
     * that erased sector 0 this import; otherwise keep last-good and refuse. */
    if (!smp_sec0_erased[k]) {
        smp_importing[k] = 0;
        return 6;
    }
    ed_smp_inval(k);
    if (st_crc32(smp_user_xip(k) + SMP_USER_DATA, h->data_len) != h->crc) {
        ed_smp_try_restore(k);
        return 3;
    }
    if (ed_project.mode == 2)
        ed_project.changed = 1;
    if (fl_write(ed_smp_slot(k), ed_smp_buf, n)) {
        ed_smp_try_restore(k);
        return 4;
    }
    ed_smp_inval(k);
    smp_user_scan(k);
    smp_importing[k] = 0;
    smp_sec0_erased[k] = 0;
    ed_smp_clear_backup(k);
    engine_brk_loops();
    return usr_nz[k] ? 0 : 5;
}

#ifndef X0X_DEBUG
#define X0X_DEBUG 0
#endif
#if X0X_DEBUG
/* development builds only (X0X_DEBUG=1; tools/build.py refuses it in a release): the clock work
 * reads and writes the chip's registers live over USB.
 *   PEEK  40 addr n        -> addr, n words      (n <= 16)
 *   POKE  41 addr value    -> addr, old, new
 *   CLOCK 42 iterations    -> 24 MHz ticks a fixed loop took (IRQs off), C0_TL_CKCNT before, after
 * A number is 5 x 7 bits, least significant first. Only these ranges, word aligned: an address
 * outside them gets no reply (a stray read of a gated block could fault). */
enum { ED_PEEK = 40, ED_POKE, ED_CLOCK };
#include "fm1_debug.h"
static uint32_t ed_u35(const uint8_t *a)
{
    return (uint32_t)a[0] | (uint32_t)a[1] << 7 | (uint32_t)a[2] << 14 | (uint32_t)a[3] << 21 | (uint32_t)a[4] << 28;
}
static void ed_w35(uint32_t v)
{
    uint32_t k;
    for (k = 0; k < 5u; k++)
        ed_b(v >> (7u * k));
}
static int ed_debug(uint32_t cmd, const uint8_t *a, uint32_t na)
{
    uint32_t addr, i;
#if X0X_DEBUG > 1                                     /* the clock work's timing loop: level 2 (room) */
    if (cmd == ED_CLOCK) {
        uint32_t it, c0, c1;
        if (na < 5u)
            return 0;
        it = ed_u35(a);
        if (!it || it > 50000000u)
            return 0;
        ed_w35(fm1_dbg_clock(it, &c0, &c1));
        ed_w35(c0);
        ed_w35(c1);
        return 1;
    }
#endif
    if (na < 10u)
        return 0;
    addr = ed_u35(a);
    if (cmd == ED_PEEK) {
        uint32_t n = ed_u35(a + 5);
        if (!n || n > 16u || !fm1_dbg_ok(addr, n))
            return 0;
        ed_w35(addr);
        for (i = 0; i < n; i++)
            ed_w35(fm1_dbg_rd(addr + 4u * i));
        return 1;
    }
    if (!fm1_dbg_ok(addr, 1))
        return 0;
    ed_w35(addr);
    ed_w35(fm1_dbg_rd(addr));
    fm1_dbg_wr(addr, ed_u35(a + 5));
    ed_w35(fm1_dbg_rd(addr));
    return 1;
}
#endif

/* Boot screen upload. Chunks sit in the existing store buffer. Flash is
 * touched only by END, and only with a whole valid record, written to the
 * inactive copy with the header last. */
static boot_stage_t bst;
static boot_io_t bio;

static int boot_dev_erase(void *ctx, uint32_t off)
{
    (void)ctx;
    fm1_wdt_feed();
    return ed_silence_erase4k(off, 0);
}
static int boot_dev_prog(void *ctx, uint32_t off, const uint8_t *src, uint32_t n)
{
    (void)ctx;
    return fl_write(off, src, n);
}
static int boot_dev_read(void *ctx, uint32_t off, uint8_t *dst, uint32_t n)
{
    (void)ctx;
    return fl_read(off, dst, n);
}
static int boot_cmd(uint32_t cmd)
{
    return cmd == ED_BOOT_INFO || (cmd >= ED_BOOT_BEGIN && cmd <= ED_BOOT_ABORT);
}
static void boot_housekeep(void)
{
    if (boot_poll(&bst, fm1_ms) == BOOT_LATE)
        store_stage_unlock();
}
static const uint8_t *boot_shown(void)
{
    const uint8_t *a, *b;
    int w;
    if (!flash_ok)
        return 0;
    a = fm1_xip_ptr(BOOT_SEC0);
    b = fm1_xip_ptr(BOOT_SEC1);
    w = boot_pick(a, b);
    return w < 0 ? 0 : (w ? b : a);
}
static void boot_finish(int rc)
{
    if (!bst.armed)
        store_stage_unlock();
    ed_b((uint32_t)rc);
}
static void ed_boot(uint32_t cmd, const uint8_t *a, uint32_t na)
{
    int rc;
    if (cmd == ED_BOOT_INFO) {
        const uint8_t *sec = boot_shown();
        const uint8_t *pay = sec ? sec + BOOT_PAY_OFF : 0;
        char l0[13], l1[22];
        boot_lines(!flash_ok ? 0 : pay, l0, l1);
        ed_b(flash_ok ? (pay && pay[0] == BOOT_KIND_CUSTOM ? 0u : 1u) : (uint32_t)BOOT_NOFLASH);
        ed_b(pay && (pay[1] & BOOT_F_PIC) ? 1u : 0u);
        ed_str(l0, 12);
        ed_str(l1, 21);
        return;
    }
    if (cmd == ED_BOOT_ABORT) {
        boot_abort(&bst);
        store_stage_unlock();
        ed_b(0);
        return;
    }
    if (cmd == ED_BOOT_READ) {
        const uint8_t *sec = boot_shown();
        uint32_t off, n, len;
        if (na < 4u || !sec) {
            ed_b(1);
            return;
        }
        off = (uint32_t)a[0] | (uint32_t)a[1] << 7 | (uint32_t)a[2] << 14;
        len = boot_u32(sec + 12);
        n = a[3] > ED_READ_MAX / 2u ? ED_READ_MAX : a[3] * 2u;
        if (off >= len) {
            ed_b(1);
            return;
        }
        if (n > len - off)
            n = len - off;
        ed_b(0);
        ed_b(off);
        ed_b(off >> 7);
        ed_b(off >> 14);
        ed_put7(sec + BOOT_PAY_OFF + off, n);
        return;
    }
    if (cmd == ED_BOOT_BEGIN) {
        uint32_t cap = 0;
        uint8_t *b;
        if (!flash_ok) {
            ed_b(BOOT_NOFLASH);
            return;
        }
        if (ui_boot_flash_busy()) {
            ed_b(BOOT_BUSY);
            return;
        }
        if (!store_stage_held()) {
            b = store_stage_lock(&cap);
            if (!b) {
                ed_b(BOOT_BUSY);
                return;
            }
            bst.buf = b;
            bst.cap = cap;
        }
        bio.erase = boot_dev_erase;
        bio.prog = boot_dev_prog;
        bio.read = boot_dev_read;
        bio.ctx = 0;
        rc = boot_begin(&bst, fm1_ms);
        if (rc != BOOT_OK) {
            bst.armed = 0;
            store_stage_unlock();
        }
        ed_b((uint32_t)rc);
        return;
    }
    if (cmd == ED_BOOT_WRITE) {
        uint32_t off = 0, n;
        if (na >= 3u)
            off = (uint32_t)a[0] | (uint32_t)a[1] << 7 | (uint32_t)a[2] << 14;
        n = na >= 3u ? ed_unpack_exact(a + 3, na - 3u, ed_smp_buf, 256u) : 0u;
        rc = boot_write(&bst, off, n ? ed_smp_buf : 0, n, fm1_ms);
        ed_b(off);
        ed_b(off >> 7);
        ed_b(off >> 14);
        boot_finish(rc);
        return;
    }
    if (cmd == ED_BOOT_END) {
        if (ui_boot_flash_busy()) {
            ed_b(BOOT_BUSY);
            return;
        }
        rc = boot_end(&bst, &bio, BOOT_SEC0, BOOT_SEC1, fm1_ms);
        boot_finish(rc);
        return;
    }
    ed_b(BOOT_BAD);
}

static int ed_install_busy(void)
{
    uint32_t k;
    if (!flash_ok || ed_project.mode || ui_project_busy() || bst.armed ||
        store_stage_held() || ed_reboot_at || usb.ota_req || usb.uboot_req)
        return 1;
    for (k = 0; k < SMP_USER_SLOTS; k++)
        if (smp_importing[k] || smp_sec0_erased[k])
            return 1;
    return 0;
}

/* START=1 token[16]; CANCEL=2 / COMMIT=3 token[16], ticket[4 x 7 bits].
 * Reply op, rc, token[16], ticket[4]; malformed envelopes reply only op, 1.
 * rc: 0 ok, 1 format, 2 busy, 3 stale/consumed, 4 changed, 5 exhausted.
 * Return true only for a consumed, valid COMMIT; caller must also enqueue its
 * entire ACK successfully before publishing the main-loop request. */
static int ed_install_handle(const uint8_t *a, uint32_t na)
{
    uint32_t op = na ? a[0] : 0, k, ticket = 0, rc = 0, any = 0;
    int same, start = 0;
    ed_b(op);
    if ((op != 1u && op != 2u && op != 3u) ||
        na != 1u + ED_INSTALL_TOKEN + (op == 1u ? 0u : 4u)) {
        ed_b(1); return 0;
    }
    for (k = 1; k < na; k++) {
        if (a[k] & 0x80u) { ed_b(1); return 0; }
        if (k <= ED_INSTALL_TOKEN) any |= a[k];
    }
    if (!any) { ed_b(1); return 0; }
    if (op != 1u)
        for (k = 0; k < 4u; k++) ticket |= (uint32_t)a[1u + ED_INSTALL_TOKEN + k] << (7u * k);
    same = ed_install.state && !memcmp(ed_install.token, a + 1, ED_INSTALL_TOKEN);
    if (op == 1u) {
        if (same) {
            ticket = ed_install.ticket;
            rc = ed_install.state == 2u ? 4u : ed_install.state == 3u ? 3u :
                 ed_install_busy() ? 2u : 0u;
        } else if (ed_install_busy()) rc = 2;
        else if (ed_install.serial == ED_INSTALL_TICKET_MAX) rc = 5;
        else {
            memcpy(ed_install.token, a + 1, ED_INSTALL_TOKEN);
            ticket = ed_install.ticket = ++ed_install.serial;
            ed_install.state = 1;
        }
    } else if (!same || ticket != ed_install.ticket || ed_install.state == 3u) rc = 3;
    else if (op == 2u) ed_install_forget();
    else if (ed_install.state == 2u) { rc = 4; ed_install_forget(); }
    else if (ed_install_busy()) { rc = 2; ed_install_forget(); }
    else {
        ed_install_forget();                         /* consume even if ACK enqueue fails */
        start = 1;
    }
    ed_b(rc);
    for (k = 0; k < ED_INSTALL_TOKEN; k++) ed_b(a[k + 1u]);
    for (k = 0; k < 4u; k++) ed_b(ticket >> (7u * k));
    return start;
}

static void ed_handle(const uint8_t *f, uint32_t n)
{
    uint32_t cmd = f[3], i;
    const uint8_t *a = f + 4;
    uint32_t na = n - 4u;
    ed_begin(cmd);
    /* Before validation: BEGIN and even failed END may restore a shadow. This
     * also covers empty-slot writes and malformed mutation attempts. Startup
     * recovery runs before any watch can exist. No other runtime path writes
     * user-slot bytes. A read or INFO must never reset this state. */
    if (cmd >= ED_SMP_BEGIN && cmd <= ED_SMP_ERASE)
        ed_install_dirty();
    switch (cmd) {
    case ED_INSTALL: {
        int start = ed_install_handle(a, na);
        int sent = ed_send();
        if (na && a[0] == 3u)
            ed_install_pending = sent == 0 && start ? 1u : 2u;
        /* Even a refused/uncertain COMMIT cannot inherit a legacy IRQ request
         * that arrived while the response was being queued. */
        return;
    }
    case ED_PROJECT:
        ed_project_handle(a, na);
        break;
    case ED_INFO:
        ed_str("X0X " X0X_VERSION, 24);
        ed_b(0);                                      /* no engines / parameters over this protocol */
        ed_b(0);
        ed_b(0);
        ed_b(NSTEPS);
        ed_b(0);
        ed_b(0);
        ed_b(0x58); ed_b(0x53); ed_b(0x47);           /* XSG: atomic sample snapshot admission */
        ed_b(1); ed_b(ED_INSTALL);
        break;
    case ED_PING:
        ed_b(0);
        break;
    case ED_DIAG: {                                   /* read only: the crash record and the Bluetooth start */
        uint32_t w[77], nw = 0, k;            /* 77 x 5 B fit ed_out (tests/diag_size_test.py) */
        const uint32_t *c = (const uint32_t *)&fm1_crash;
        for (k = 0; k < sizeof fm1_crash / 4u; k++)
            w[nw++] = c[k];
        w[nw++] = bootguard.failed;
        w[nw++] = bootguard.pending;
#if X0X_BLE
        nw += ble_diag(w + nw, (uint32_t)(sizeof w / 4u) - nw);
#endif
        ed_b(nw);
        for (k = 0; k < nw; k++) {
            ed_b(w[k]);
            ed_b(w[k] >> 7);
            ed_b(w[k] >> 14);
            ed_b(w[k] >> 21);
            ed_b(w[k] >> 28);
        }
        break;
    }
#if BOARD_SMK37
    case ED_INLOG:                                    /* read only: the inbound recorder (main_fm1.c) */
        smk_inlog_reply(na >= 1u ? a[0] : 0u);
        break;
#endif
    case ED_SMP_BEGIN:
    case ED_SMP_ERASE:
        if (na < 1u || a[0] >= SMP_USER_SLOTS || !flash_ok)
            return;
        ed_b(a[0]);
        if (ed_project_samples_locked())
            ed_b(4u);
        else if (cmd == ED_SMP_BEGIN)
            ed_b(ed_smp_begin(a[0]) ? 1u : 0u);
        else
            ed_b(ed_smp_erase(a[0], 1u) ? 1u : 0u);
        break;
    case ED_SMP_WRITE: {
        uint32_t off, len, rc = 0, took;
        if (na < 5u || a[0] >= SMP_USER_SLOTS || !flash_ok)
            return;
        off = (uint32_t)a[1] | (uint32_t)a[2] << 7 | (uint32_t)a[3] << 14;
        len = ed_unpack7(a + 4, na - 4u, ed_smp_buf, 256u);
        if (off < SMP_USER_DATA || (off & 0xFFu) || !len || off + len > SMP_USER_SIZE(a[0]))
            rc = 1;
        else if (ed_project_samples_locked() ||
                 (!smp_importing[a[0]] && usr_nz[a[0]]))
            rc = 4;
        else {
            if (ed_project.mode == 2)
                ed_project.changed = 1;
            if (ed_smp_erase_for_write(a[0], off, &took))
                rc = 2;
            if (!rc) {
                /* Sector-0 backup/restore reuses ed_smp_buf; re-unpack after erase. */
                len = ed_unpack7(a + 4, na - 4u, ed_smp_buf, 256u);
                if (fl_write(ed_smp_slot(a[0]) + off, ed_smp_buf, len))
                    rc = 3;
            }
        }
        ed_b(a[0]);
        ed_b(off);
        ed_b(off >> 7);
        ed_b(off >> 14);
        ed_b(rc);
        break;
    }
    case ED_SMP_END:
        if (na < 2u || a[0] >= SMP_USER_SLOTS || !flash_ok)
            return;
        ed_b(a[0]);
        ed_b(ed_project_samples_locked() ? 4u : (uint32_t)ed_smp_end(a[0], a + 1, na - 1u));
        break;
#if X0X_DEBUG
    case ED_PEEK:
    case ED_POKE:
    case ED_CLOCK:
        if (!ed_debug(cmd, a, na))
            return;
        break;
#endif
    case ED_BOOT_INFO:
    case ED_BOOT_BEGIN:
    case ED_BOOT_WRITE:
    case ED_BOOT_READ:
    case ED_BOOT_END:
    case ED_BOOT_ABORT:
        ed_boot(cmd, a, na);
        break;
    case ED_SMP_READ: {                              /* X0X: slot, offset (3 x 7 bits, from the slot's start,
                                                      * its header included), count -> slot, offset, the bytes
                                                      * packed 7 to 8 (as WRITE takes them) */
        uint32_t off, n;
        const uint8_t *src;
        if (na < 5u || a[0] >= SMP_USER_SLOTS)
            return;
        off = (uint32_t)a[1] | (uint32_t)a[2] << 7 | (uint32_t)a[3] << 14;
        n = a[4] > ED_READ_MAX / 2u ? ED_READ_MAX : a[4] * 2u;   /* the count is in pairs (7 bits) */
        if (off >= SMP_USER_SIZE(a[0]))
            return;
        if (n > SMP_USER_SIZE(a[0]) - off)
            n = SMP_USER_SIZE(a[0]) - off;
        src = smp_user_xip(a[0]) + off;
        ed_b(a[0]);
        ed_b(off);
        ed_b(off >> 7);
        ed_b(off >> 14);
        ed_put7(src, n);
        break;
    }
    case ED_SMP_INFO: {                              /* count, size (KiB, 7 bits: the SMALLEST slot, so an older
                                                      * tool that takes one size for all never overfills one),
                                                      * per slot: zones, name, used KiB (7 bits); then the X0X
                                                      * extension 'X' 1, per slot: flash offset and size in 4 KiB
                                                      * sectors and used KiB, 14 bits each (2 x 7, low first).
                                                      * An older tool stops before the extension. */
        uint32_t mn = SMP_USER_MAX;
        for (i = 0; i < SMP_USER_SLOTS; i++)
            mn = SMP_USER_SIZE(i) < mn ? SMP_USER_SIZE(i) : mn;
        ed_b(SMP_USER_SLOTS);
        ed_b(mn / 1024u > 127u ? 127u : mn / 1024u);
        for (i = 0; i < SMP_USER_SLOTS; i++) {
            const smp_user_hdr_t *h = (const smp_user_hdr_t *)smp_user_xip(i);
            char nm[9] = {0};
            uint32_t j;
            ed_b(usr_nz[i]);
            for (j = 0; usr_nz[i] && j < 8u; j++)
                nm[j] = h->name[j] >= 32 && h->name[j] < 127 ? h->name[j] : 0;
            ed_str(nm, 8);
            j = usr_nz[i] ? (h->data_len + 1023u) / 1024u : 0u;
            ed_b(j > 127u ? 127u : j);
        }
        ed_b('X');
        ed_b(1);
        for (i = 0; i < SMP_USER_SLOTS; i++) {
            const smp_user_hdr_t *h = (const smp_user_hdr_t *)smp_user_xip(i);
            uint32_t v[3], j;
            v[0] = SMP_USER_OFF(i) / 0x1000u;
            v[1] = SMP_USER_SIZE(i) / 0x1000u;
            v[2] = usr_nz[i] ? (h->data_len + 1023u) / 1024u : 0u;
            for (j = 0; j < 3u; j++) {
                ed_b(v[j]);
                ed_b(v[j] >> 7);
            }
        }
        break;
    }
#if X0X_BLE
    case ED_BT_TEST: {
        uint32_t op = na > 0u ? a[0] : 0u;
        if (op > 4u)
            return;
        if (ui_project_busy() && (op == 1u || op == 2u))
            return;                                 /* radio reset/reboot cannot interrupt sample recovery */
        if (op >= 3u) {     /* 3: the timer 5 frame watch (fm1_guard.h), last boot's, then hits now;
                             * 4: core 1's records (fm1_cpu1.h): core 0 seen stopping, the RAM canary */
            const uint32_t *t = op == 3u ? (const uint32_t *)&fm1_t5w_prev : (const uint32_t *)&fm1_c0_dead;
            const uint32_t *g = (const uint32_t *)&fm1_can;
            const uint32_t nt = op == 3u ? sizeof fm1_t5w_prev / 4u : sizeof fm1_c0_dead / 4u;
            const uint32_t n = nt + (op == 3u ? 1u : sizeof fm1_can / 4u);
            uint32_t k;
            ed_b(op);
            ed_b(n);
            for (k = 0; k < n; k++) {
                uint32_t v = k < nt ? t[k] : op == 3u ? fm1_t5w.hits : g[k - nt];
                ed_b(v);
                ed_b(v >> 7);
                ed_b(v >> 14);
                ed_b(v >> 21);
                ed_b(v >> 28);
            }
            break;
        }
        if (op == 1u) {
            plat_ble_set(0);                          /* as BLUETOOTH OFF: the next power-on tries again */
            plat_ble_set((proj.set.bt & 1u) != 0u);   /* the setting itself does not change */
        }
        if (op == 2u)
            ed_reboot_at = fm1_ms + 1u;               /* after this reply is out (main loop) */
        ed_b(op);
        ed_b(proj.set.bt & 1u);
        ed_b(ble_guard.blocked & 1u);
        ed_b((uint32_t)plat_ble_state());
        break;
    }
    case ED_CTL_READ: {
        uint32_t off, n;
        const uint8_t *src;
        _Static_assert(XB_FLASH_OFF == FL_BLE_LO && XB_FLASH_SIZE == FL_BLE_HI - FL_BLE_LO,
                       "ED_CTL_READ: the Bluetooth block is FL_BLE");
        if (na < 4u)
            return;
        off = (uint32_t)a[0] | (uint32_t)a[1] << 7 | (uint32_t)a[2] << 14;
        n = a[3] > ED_READ_MAX / 2u ? ED_READ_MAX : a[3] * 2u;
        if (off >= XB_FLASH_SIZE)
            return;
        if (n > XB_FLASH_SIZE - off)
            n = XB_FLASH_SIZE - off;
        src = fm1_xip_ptr(XB_FLASH_OFF) + off;     /* the app area: reads decrypted, as core 1 runs it */
        ed_b(off);
        ed_b(off >> 7);
        ed_b(off >> 14);
        ed_put7(src, n);
        break;
    }
#endif
    default:
        return;                                       /* not ours: no reply */
    }
    ed_send();
}

/* Return 1 only when this check left a non-editor frame pending for OTA. */
static int ed_service(void)
{
    const uint8_t *p;
    uint32_t n;
    if (ed_project.mode && !ed_project.recovery && fm1_ms - ed_project.at >= 15000u)
        ed_project_end(0);
    boot_housekeep();
    if (!ota_frame_get(&p, &n))
        return 0;
    if (n < 4u || p[0] != ED_HDR0 || p[1] != ED_HDR1 || p[2] != ED_HDR2) {
        if (ed_project.mode) {
            ota_frame_done();                        /* OTA and project operations share scratch */
            return 0;
        }
        return 1;                                    /* this same pending frame belongs to ota_service() */
    }
    /* Boot writes are longer than the 64-byte stack copy below. A truncated
     * frame would fail the check and must not be stored. */
    if (p[3] == ED_PROJECT || (p[3] >= ED_SMP_BEGIN && p[3] <= ED_SMP_READ) || boot_cmd(p[3])) {
        ed_handle(p, n);
        ota_frame_done();
        return 0;
    }
    {
        uint8_t f[64];                                /* (on the stack: ed_handle keeps no pointer to it) */
        uint32_t k = n > sizeof f ? sizeof f : n, i;
        for (i = 0; i < k; i++)
            f[i] = p[i];
        ota_frame_done();
        ed_handle(f, k);
    }
    return 0;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Gate the code pipeline on a persisted stage thread.

Stages run in order: Audit, Implement, Test, Validate, Merge, Publish.
The caller starts a new top-level thread for a stage and passes that thread
id here. record_thread() stores the stage, thread id, timestamp, and status
in the ledger. Each stage needs its own thread id; an id already stored on
any transition is rejected before the ledger is saved. advance() reads the
ledger and moves the current stage only when that new id is already on disk.
note_helper() records a subagent on the stage that is already running.
A missing, null, subagent, or already-used id never changes the current stage.

The ledger is cloud-handoff/pipeline.json. Historical HANDOFF directories
stay evidence; this file is the record the pipeline consults.
"""
import argparse
import json
import os
from datetime import datetime
from pathlib import Path
import sys

SCHEMA = 1
STAGES = ('Audit', 'Implement', 'Test', 'Validate', 'Merge', 'Publish')
ROOT = Path(__file__).resolve().parents[1]
DEFAULT_LEDGER = ROOT / 'cloud-handoff' / 'pipeline.json'


class HandoffError(ValueError):
    """The pipeline refused to record a handoff or to advance."""


def empty_ledger():
    return {
        'schema': SCHEMA,
        'stages': list(STAGES),
        'current': None,
        'transitions': [],
        'helpers': [],
    }


def _next(current):
    if current is None:
        return STAGES[0]
    return STAGES[STAGES.index(current) + 1] if current != STAGES[-1] else None


def _plain_id(value, message):
    if not isinstance(value, str) or value == '' or any(ch.isspace() for ch in value):
        raise HandoffError(message)
    return value


def _timestamp(value):
    if not isinstance(value, str) or value == '' or any(ch.isspace() for ch in value):
        raise HandoffError('timestamp required')
    text = value[:-1] + '+00:00' if value.endswith('Z') else value
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as error:
        raise HandoffError('timestamp must be ISO-8601 with a timezone') from error
    if parsed.tzinfo is None:
        raise HandoffError('timestamp must be ISO-8601 with a timezone')
    return value


def _stage(value):
    if value not in STAGES:
        raise HandoffError('unknown stage')
    return value


def save(path, state):
    """Replace the ledger only after its new bytes are flushed."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f'.{path.name}.{os.getpid()}.tmp')
    data = (json.dumps(state, indent=2) + '\n').encode()
    try:
        descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
        try:
            os.write(descriptor, data)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        os.replace(temporary, path)
    except Exception:
        try:
            temporary.unlink()
        except OSError:
            pass
        raise
    directory = os.open(path.parent, os.O_RDONLY)
    try:
        os.fsync(directory)
    finally:
        os.close(directory)


def load(path):
    path = Path(path)
    if not path.is_file():
        raise HandoffError('no handoff ledger')
    try:
        state = json.loads(path.read_text(encoding='utf-8'))
    except (OSError, json.JSONDecodeError) as error:
        raise HandoffError('unsupported handoff ledger') from error
    if not isinstance(state, dict) or state.get('schema') != SCHEMA:
        raise HandoffError('unsupported handoff ledger')
    if state.get('stages') != list(STAGES):
        raise HandoffError('ledger stages do not match the pipeline')
    if 'current' not in state or 'transitions' not in state:
        raise HandoffError('unsupported handoff ledger')
    current = state['current']
    transitions = state['transitions']
    if current is not None and current not in STAGES:
        raise HandoffError('unsupported handoff ledger')
    if not isinstance(transitions, list) or any(not isinstance(item, dict) for item in transitions):
        raise HandoffError('unsupported handoff ledger')
    helpers = state.get('helpers', [])
    if not isinstance(helpers, list) or any(not isinstance(item, dict) for item in helpers):
        raise HandoffError('unsupported handoff ledger')
    state['helpers'] = helpers
    return state


def init(path):
    path = Path(path)
    if path.exists():
        raise HandoffError('handoff ledger already exists')
    state = empty_ledger()
    save(path, state)
    return state


def _helper_ids(state):
    return {item.get('subagent_id') for item in state['helpers']}


def record_thread(path, stage, thread_id, timestamp):
    """Store one new thread for the next stage. Do not change the current stage."""
    state = load(path)
    stage = _stage(stage)
    expected = _next(state['current'])
    if expected is None:
        raise HandoffError('pipeline is complete')
    if stage != expected:
        raise HandoffError('stage is out of order')
    if any(item.get('stage') == stage for item in state['transitions']):
        raise HandoffError('stage handoff already recorded')
    thread_id = _plain_id(thread_id, 'thread id required')
    if thread_id in _helper_ids(state):
        raise HandoffError('stage handoff requires a new thread, not a subagent')
    if any(item.get('thread_id') == thread_id for item in state['transitions']):
        raise HandoffError('each stage requires its own thread')
    state['transitions'].append({
        'stage': stage,
        'thread_id': thread_id,
        'timestamp': _timestamp(timestamp),
        'status': 'recorded',
        'kind': 'thread',
    })
    save(path, state)
    return state


def _recorded_thread(state, stage):
    found = [item for item in state['transitions'] if item.get('stage') == stage]
    if len(found) != 1:
        return None
    item = found[0]
    thread_id = item.get('thread_id')
    if item.get('kind') != 'thread' or item.get('status') != 'recorded':
        return None
    if not isinstance(thread_id, str) or thread_id == '' or any(ch.isspace() for ch in thread_id):
        return None
    if thread_id in _helper_ids(state):
        raise HandoffError('stage handoff requires a new thread, not a subagent')
    if any(other is not item and other.get('thread_id') == thread_id for other in state['transitions']):
        raise HandoffError('each stage requires its own thread')
    return item


def advance(path):
    """Move one stage forward only when its thread id is already in the ledger."""
    state = load(path)
    stage = _next(state['current'])
    if stage is None:
        raise HandoffError('pipeline is complete')
    entry = _recorded_thread(state, stage)
    if entry is None:
        raise HandoffError('pipeline does not advance until the thread id is recorded')
    state['current'] = stage
    entry['status'] = 'active'
    save(path, state)
    return state


def handoff(path, stage, thread_id, timestamp):
    """Persist the new thread, then advance by reading that persisted ledger."""
    record_thread(path, stage, thread_id, timestamp)
    return advance(path)


def note_helper(path, stage, subagent_id, timestamp):
    """Record in-stage help. This does not hand the stage to the subagent."""
    state = load(path)
    stage = _stage(stage)
    if state['current'] != stage:
        raise HandoffError('subagents only help inside a stage that is already running')
    subagent_id = _plain_id(subagent_id, 'subagent id required')
    if any(item.get('thread_id') == subagent_id for item in state['transitions']):
        raise HandoffError('stage handoff requires a new thread, not a subagent')
    if any(item.get('stage') == stage and item.get('subagent_id') == subagent_id for item in state['helpers']):
        raise HandoffError('subagent already recorded for this stage')
    state['helpers'].append({
        'stage': stage,
        'subagent_id': subagent_id,
        'timestamp': _timestamp(timestamp),
        'status': 'in-stage',
    })
    save(path, state)
    return state


def _emit(state):
    json.dump(state, sys.stdout, indent=2)
    print()


def _command(commands, name, help_text):
    command = commands.add_parser(name, help=help_text)
    command.add_argument('--ledger', type=Path, default=argparse.SUPPRESS)
    return command


def main(argv=None):
    parser = argparse.ArgumentParser(description='Persist a stage thread before the pipeline advances.')
    parser.add_argument('--ledger', type=Path, default=DEFAULT_LEDGER)
    commands = parser.add_subparsers(dest='command', required=True)

    _command(commands, 'init', 'create the handoff ledger')
    _command(commands, 'show', 'print the handoff ledger')
    _command(commands, 'advance', 'enter the next stage when its thread id is stored')

    recorded = _command(commands, 'record', 'store the next stage thread without advancing')
    recorded.add_argument('--stage', required=True)
    recorded.add_argument('--thread-id', required=True)
    recorded.add_argument('--timestamp', required=True)

    delivered = _command(commands, 'handoff', 'store the next stage thread, then advance')
    delivered.add_argument('--stage', required=True)
    delivered.add_argument('--thread-id', required=True)
    delivered.add_argument('--timestamp', required=True)

    helper = _command(commands, 'helper', 'note a subagent helping the running stage')
    helper.add_argument('--stage', required=True)
    helper.add_argument('--subagent-id', required=True)
    helper.add_argument('--timestamp', required=True)

    args = parser.parse_args(argv)
    path = args.ledger
    if args.command == 'init':
        state = init(path)
    elif args.command == 'show':
        state = load(path)
    elif args.command == 'advance':
        state = advance(path)
    elif args.command == 'record':
        state = record_thread(path, args.stage, args.thread_id, args.timestamp)
    elif args.command == 'handoff':
        state = handoff(path, args.stage, args.thread_id, args.timestamp)
    else:
        state = note_helper(path, args.stage, args.subagent_id, args.timestamp)
    _emit(state)
    return 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except HandoffError as error:
        print('Stage handoff: ' + str(error), file=sys.stderr)
        sys.exit(1)

